package com.example.rokidgeminisecretary;
import android.app.*;import android.widget.*;import org.json.*;import java.io.*;import java.nio.file.*;
final class MeetingReviewDialog {
 static void show(MainActivity owner,String id){showAt(owner,id,0,false);}
 static void showAt(MainActivity owner,String id,long anchor,boolean searched){if(anchor<0||anchor>7260000)throw new IllegalArgumentException("再生位置が不正です");new Thread(()->{try{File folder=MeetingAudioStore.folder(owner,id);JSONObject meta=MeetingAudioStore.meta(folder);JSONArray marks=BookmarkStore.read(folder);JSONObject notes=BookmarkNotes.read(owner,id);JSONArray timeline=TranscriptTimeline.read(owner,id);StringBuilder result=new StringBuilder();for(String name:new String[]{"summary.gcm","transcript.gcm"}){File file=new File(folder,name);if(file.isFile()&&file.length()<2500000){String text=new String(DeviceSecrets.photos().decrypt(Files.readAllBytes(file.toPath())),"UTF-8");result.append(name.equals("summary.gcm")?"要約\n":"\n文字起こし\n").append(text.length()>100000?text.substring(0,100000)+"\n（表示上限。全文はWebから保存できます）":text);}}String body=result.toString();owner.runOnUiThread(()->{LinearLayout box=new LinearLayout(owner);box.setOrientation(1);box.setPadding(20,12,20,12);TextView status=new TextView(owner);status.setText("しおりの位置は保存された音声の時間です。再生ボタンを押すまで音は出しません。");box.addView(status);MeetingLocalPlayer player=new MeetingLocalPlayer(owner,id,meta.optInt("parts",meta.optJSONArray("parts")==null?0:meta.optJSONArray("parts").length()),status);if(searched){TextView found=new TextView(owner);found.setText("検索した文字起こし区間：約"+anchor/1000+"秒。正確な発言時刻ではありません");box.addView(found);Button jump=new Button(owner);jump.setText("検索箇所の区間から再生");jump.setOnClickListener(v->player.play(anchor));box.addView(jump);}Button play=new Button(owner);play.setText("最初から再生");play.setOnClickListener(v->player.play(0));box.addView(play);for(int i=0;i<marks.length();i++){JSONObject mark=marks.optJSONObject(i);Button b=new Button(owner);b.setText(mark.optLong("audioMs")/60000+":"+String.format(java.util.Locale.ROOT,"%02d",mark.optLong("audioMs")/1000%60)+" "+mark.optString("label")+" から再生");b.setOnClickListener(v->player.play(mark.optLong("audioMs")));box.addView(b);JSONObject saved=notes.optJSONObject(mark.optString("id"));EditText memo=new EditText(owner);memo.setHint("このしおりのメモ（決定事項・あとで確認など）");memo.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(800)});memo.setText(saved==null?"":saved.optString("text"));box.addView(memo);Button save=new Button(owner);save.setText("しおりメモを保存");final int[] revision={saved==null?0:saved.optInt("revision")};save.setOnClickListener(v->{String value=memo.getText().toString();save.setEnabled(false);new Thread(()->{try{JSONObject savedNote=BookmarkNotes.save(owner,new JSONObject().put("meeting",id).put("bookmark",mark.getString("id")).put("revision",revision[0]).put("text",value));owner.runOnUiThread(()->{revision[0]=savedNote.optInt("revision");save.setEnabled(true);status.setText("しおりメモを保存しました");});}catch(Exception e){owner.runOnUiThread(()->{save.setEnabled(true);status.setText(e.getMessage());});}},"BookmarkNote").start();});box.addView(save);}for(int k=0;k<timeline.length();k++){JSONObject segment=timeline.optJSONObject(k);TextView words=new TextView(owner);words.setText("約"+segment.optLong("startMs")/1000+"〜"+segment.optLong("endMs")/1000+"秒\n"+segment.optString("text"));words.setTextIsSelectable(true);if(searched&&segment.optLong("startMs")==anchor)words.setBackgroundColor(0xFFFFF2AA);box.addView(words);Button seek=new Button(owner);seek.setText("この文字起こし区間の冒頭から再生");seek.setOnClickListener(v->player.play(segment.optLong("startMs")));box.addView(seek);}Button candidates=new Button(owner);candidates.setText("この会議の要約から保留候補を確認");candidates.setOnClickListener(v->MeetingActionsDialog.show(owner,id));box.addView(candidates);Button inbox=new Button(owner);inbox.setText("保留候補・案件を確認");inbox.setOnClickListener(v->new SecretaryInboxDialog(owner).show());box.addView(inbox);Button stop=new Button(owner);stop.setText("再生を停止");stop.setOnClickListener(v->player.stop());box.addView(stop);TextView text=new TextView(owner);text.setTextIsSelectable(true);text.setText(body.isEmpty()?"文字起こし・要約はまだありません":body);box.addView(text);ScrollView scroll=new ScrollView(owner);scroll.addView(box);AlertDialog dialog=new AlertDialog.Builder(owner).setTitle("元の会議記録・しおり").setView(scroll).setPositiveButton("閉じる",null).create();dialog.setOnDismissListener(d->player.stop());dialog.show();});}catch(Exception e){owner.runOnUiThread(()->Toast.makeText(owner,"元の会議記録を開けません",Toast.LENGTH_LONG).show());}},"MeetingReview").start();}
 private MeetingReviewDialog(){}
}
